  const tree=h('div','file-tree'),folder=h('details','tree-folder');folder.open=true;const sum=h('summary');sum.append(h('strong','','DOCKYARD'));folder.append(sum);
  const entries=['welcome','workspace.js','theme.css','preview','README.md','notes.md'];
  for(const id of entries){const row=action('',()=>openFile(id),'file-row');row.dataset.file=id;row.append(h('span',`file-icon ${id.endsWith('.css')?'css':id.endsWith('.md')?'md':''}`,id.endsWith('.js')?'JS':id.endsWith('.css')?'#':id==='welcome'?'◈':id==='preview'?'◫':'M↓'),h('span','',id==='welcome'?'Overview':id==='preview'?'Live preview':id));folder.append(row);}
  const internal=h('details','tree-folder');internal.open=true;const internalSum=h('summary');internalSum.append(h('strong','','COMPONENT'));internal.append(internalSum);
