  function refresh(){const active=mgr.ActiveModel;if(active && !['properties','tree','output','history'].includes(active.ContentId))inspectedId=active.ContentId;const model=mgr.Find(inspectedId)||mgr.Layout.LastFocusedDocument;if(!model)return;inspectedId=model.ContentId;title.textContent=model.Title;kind.textContent=model.constructor.name;if(document.activeElement!==titleInput)titleInput.value=model.Title;idLabel.textContent=model.ContentId;state.textContent=model.IsAutoHidden?'Auto-hidden':model.IsHidden?'Hidden':model.IsFloating?'Floating':'Docked';parent.textContent=model.Parent?.constructor.name.replace('Layout','')||'—';for(const[key,field]of fields){field.row.hidden=!(key in model);field.input.checked=!!model[key];}}
