function consoleContent(_model,mgr){const root=tool(),lines=h('div','console-lines','Dockyard command console\nType help for available commands. JavaScript evaluation is intentionally disabled.\n'),row=h('form','console-input-row'),input=h('input');input.placeholder='help';input.setAttribute('aria-label','Console command');row.append(h('span','','›'),input);row.addEventListener('submit',e=>{e.preventDefault();const command=input.value.trim();input.value='';let result;try{const[name,...rest]=command.split(/\s+/);const id=rest.join(' '),item=mgr.Find(id);switch(name){case'help':result='help · layout · documents · float <ContentId> · dock <ContentId> · hide <ContentId> · show <ContentId> · clear';break;case'layout':result=mgr.SaveLayout('json');break;case'documents':result=AD.contents(mgr.Layout).map(x=>`${x.ContentId} — ${x.Title}`).join('\n');break;case'float':result=!!mgr.Float(item);break;case'dock':result=!!mgr.Dock(item);break;case'hide':result=item instanceof AD.LayoutAnchorable?item.Hide():'Tool window not found';break;case'show':result=!!showTool(id);break;case'clear':lines.textContent='';return;default:result='Unknown command. Type help.';}}catch(error){result=error.message;}lines.textContent+=`\n› ${command}\n${result}\n`;lines.scrollTop=lines.scrollHeight;});root.append(lines,row);return root;}
