function sourcesContent(){const root=tool(),intro=h('div','sources-intro','This panel is bound to an ObservableCollection. Add or remove an item here and its document is created or removed by DocumentsSource.'),buttons=h('div','sources-actions'),list=h('div','source-list');buttons.append(action('＋ Add source item',()=>sourceDocuments.Add({ContentId:`source-${++sourceCounter}`,Title:`Bound item ${sourceCounter}`,message:'Created through DocumentsSource.'})),action('Clear',()=>sourceDocuments.Clear()));root.append(intro,buttons,list);const refresh=()=>list.replaceChildren(...sourceDocuments.map(item=>{const row=h('div','source-row');row.append(action(item.Title,()=>manager.Activate(manager.Find(item.ContentId)),''),action('×',()=>sourceDocuments.Remove(item),''));return row;}));const dispose=sourceDocuments.CollectionChanged.add(refresh);refresh();return{element:root,dispose};}
function componentsContent(){const root=tool(),list=h('div','palette-list');const entries=[['＋','Document',newDocument],['◫','Live preview',()=>openFile('preview')],['↗','Float active',()=>manager.Float(manager.ActiveModel)],['▥','Split group',()=>manager.NewTabGroup(manager.ActiveModel,'Vertical')],['≡','API reference',()=>openFile('reference')],['⊞','Bound sources',()=>showTool('sources')],['◴','History',()=>showTool('history')],['✎','Scratchpad',()=>showTool('scratchpad')]];for(const[glyph,label,run]of entries){const node=action('',run,'palette-tile');node.append(h('span','',glyph),document.createTextNode(label));list.append(node);}root.append(heading('Add to your workspace'),list);return root;}
function scratchpadContent(){const root=h('div','scratchpad'),input=h('textarea');input.placeholder='Jot down a thought…';input.setAttribute('aria-label','Scratchpad notes');try{input.value=localStorage.getItem('dockyard.scratchpad')||'';}catch{}input.addEventListener('input',()=>{try{localStorage.setItem('dockyard.scratchpad',input.value);}catch{}});root.append(h('label','','Notes that stay with you'),input);return root;}
function referenceContent(model){const root=h('article','reference-document');root.append(h('div','document-kicker','AVALONDOCK WEB / 0.1.0'),h('h2','',model.ContentId==='shortcuts'?'A keyboard-friendly workspace.':'A model you already recognize.'),h('p','','A dependency-free JavaScript docking component with observable layout models, real DOM content, and an AvalonDock-inspired PascalCase API.'));
  const rows=model.ContentId==='shortcuts'?[
    ['Ctrl + Tab','Open the document and tool-window navigator. Release Control or press Enter to activate.'],['F6 / Shift + F6','Move focus between panes.'],['Ctrl + F4','Close the active window, respecting capabilities and cancellation.'],['Shift + F10','Open the active tab’s context menu.'],['Arrow keys','Navigate focused tabs and menus; resize a focused splitter.'],['Shift / Alt + arrows','On splitters, use large / fine resize increments.'],['Alt + Shift + arrows','Reorder the focused document tab.'],['Ctrl + Z / Ctrl + Y','Undo / redo layout changes when not editing text.'],['Ctrl + K','Open the sample application command palette.'],['Escape','Cancel a drag, dismiss auto-hide, or close a menu.'],['Ctrl during drag','Suspend docking to place a floating window.']
  ]:[
    ['DockingManager','Owns the layout, commands, rendering, sources, events, and persistence.'],['LayoutRoot / LayoutPanel','A typed, observable tree of nested horizontal and vertical splits.'],['LayoutDocument','Document tabs, split groups, floating, activation, and cancelable closing.'],['LayoutAnchorable','Tool windows with docking, hiding, grouped auto-hide, and tabbed-document placement.'],['XmlLayoutSerializer','Reads and writes the common AvalonDock layout structure; content is rebound by ContentId.'],['DocumentsSource','ObservableCollection or array binding with explicit RefreshSources for changed array data.'],['LayoutItemTemplate','Return a DOM Node, text, or { element, dispose }. Content factories are trusted application code.'],['GetLayoutItemFromModel','Access RelayCommand-style commands with CanExecute and Execute.'],['PropertyChanged','Subscribe with model.PropertyChanged.add((sender, args) => …).'],['<avalon-dock>','Reusable custom element, with JavaScript or declarative layout initialization.']
  ];const table=h('table','reference-table');for(const[a,b]of rows){const row=h('tr');row.append(h('td','',a),h('td','',b));table.append(row);}root.append(table,h('h3','','Web-native, not a WPF runtime'),h('p','','DOM nodes replace WPF controls, callbacks replace DataTemplates, and CSS replaces resource dictionaries. Browser floating windows are in-page by default; explicit pop-outs are subject to browser permissions. XAML, CLR inheritance, dependency-property binding, and native HWND behavior are not emulated.'),h('h3','','Create and save a workspace'),h('pre','',snippet+'\n\nconst xml = new XmlLayoutSerializer(manager).Serialize();'));
  const protection=h('label','property-row'),check=h('input');check.type='checkbox';check.checked=protectModified;check.addEventListener('change',()=>{protectModified=check.checked;toast(`Unsaved-document close protection ${protectModified?'enabled':'disabled'}.`);});protection.append(check,document.createTextNode('Demonstrate cancelable closing: protect modified editor buffers'));root.append(protection);return root;}

factories.set('welcome',welcomeContent);factories.set('preview',previewContent);factories.set('explorer',explorerContent);factories.set('properties',propertiesContent);factories.set('output',outputContent);factories.set('tree',treeContent);factories.set('search',searchContent);factories.set('console',consoleContent);factories.set('problems',validationContent);factories.set('history',historyContent);factories.set('sources',sourcesContent);factories.set('components',componentsContent);factories.set('scratchpad',scratchpadContent);factories.set('reference',referenceContent);factories.set('shortcuts',referenceContent);
function createLayout(preset='development') {
  const docs = ['welcome','workspace.js','preview'].map(makeDocument);
  const documentPane=new AD.LayoutDocumentPane({Id:'documents-main',DockMinWidth:270,DockMinHeight:170,Children:docs});
  const docsGroup=new AD.LayoutDocumentPaneGroup({Id:'document-groups',Children:[documentPane]});
  const left=new AD.LayoutAnchorablePane({Id:'tools-left',DockWidth:215,DockMinWidth:160,Children:[makeTool('explorer'),makeTool('search')]});
  const right=new AD.LayoutAnchorablePane({Id:'tools-right',DockWidth:245,DockMinWidth:195,Children:[makeTool('properties'),makeTool('tree')]});
  const bottom=new AD.LayoutAnchorablePane({Id:'tools-bottom',DockHeight:preset==='debug'?270:176,DockMinHeight:100,Children:[makeTool('output'),makeTool('console'),makeTool('problems')]});
  const center=new AD.LayoutPanel({Id:'center',Orientation:'Vertical',Children:[docsGroup,bottom]});
  const root=new AD.LayoutRoot({RootPanel:new AD.LayoutPanel({Id:'root-panel',Children:[left,center,right]})});
  root.RightSide.Children.Add(new AD.LayoutAnchorGroup({Children:[makeTool('history')]}));root.LeftSide.Children.Add(new AD.LayoutAnchorGroup({Children:[makeTool('components')]}));root.BottomSide.Children.Add(new AD.LayoutAnchorGroup({Children:[makeTool('scratchpad')]}));root.Hidden.Add(makeTool('sources'));
  if(preset==='focus'){for(const pane of[left,right,bottom])for(const content of pane.Children.ToArray())root.Hidden.Add(content);root.RootPanel.Children.Remove(left);root.RootPanel.Children.Remove(right);center.Children.Remove(bottom);}
  if(preset==='design'){const second=new AD.LayoutDocumentPane({Id:'documents-preview',Children:[docs[2]]});docsGroup.Children.Add(second);documentPane.SelectedContentIndex=documentPane.Children.IndexOf(docs[1]);}
  if(preset==='debug'){documentPane.SelectedContentIndex=documentPane.Children.IndexOf(docs[1]);bottom.SelectedContentIndex=1;}
  root.ActiveContent=preset==='debug'||preset==='design'?docs[1]:docs[0];return root;
}
function applyPreset(name='development') {currentPreset=name;sourceDocuments.Clear();manager.Layout=createLayout(name);$('#preset-select').value=name;$('#preset-caption').textContent={development:'Development',focus:'Focus',design:'Design review',debug:'Debugging'}[name];manager.ClearHistory();log(`Applied ${name} workspace preset.`);}
manager=new AD.DockingManager($('#dock'),{
  Layout:createLayout(),Theme:'dark',AllowMixedOrientation:true,EnableHistory:true,HistoryLimit:80,StorageKey:storageAvailable?'dockyard.layout.v1':null,AutoSave:storageAvailable,
  LayoutItemTemplate:(content,model,mgr)=>{if(typeof content==='function')return content(model,mgr);if(content?.nodeType)return content;if(content&&typeof content==='object'){const node=h('article','reference-document');node.append(h('div','document-kicker','OBSERVABLE COLLECTION'),h('h2','',model.Title),h('p','',content.message||'Bound content'),h('pre','',JSON.stringify(content,null,2)));return node;}return String(content??'');}
});
manager.DocumentsSource=sourceDocuments;
function updateStatus(){const all=AD.contents(manager.Layout),active=manager.ActiveModel;$('#active-status').textContent=active?.Title||'No active window';$('#window-count').textContent=`${all.filter(x=>x instanceof AD.LayoutDocument).length} documents · ${all.filter(x=>x instanceof AD.LayoutAnchorable).length} tools`;$('#undo-layout').disabled=!manager.CanUndo;$('#redo-layout').disabled=!manager.CanRedo;$('#status-save').textContent=manager.StorageKey?'✓ Local autosave':'Save workspace';}
listen(manager,['LayoutUpdated','LayoutChanged','ActiveContentChanged','HistoryChanged'],updateStatus);
manager.ContentMoved.add((_s,e)=>log(`${e.Operation}: ${(e.Contents||[]).map(x=>x.Title).join(', ')}`));
manager.DocumentClosed.add((_s,e)=>log(`Closed document: ${e.Document?.Title||'document'}`));
manager.AnchorableHidden.add((_s,e)=>log(`Hidden tool: ${e.Anchorable?.Title||'window'}`));
manager.LayoutChanged.add(()=>log('Layout restored; content rebound by ContentId.'));
manager.Error.add((_s,e)=>{log(`${e.Operation}: ${e.Error?.message||'error'}`,'warn');toast(e.Error?.message||'Operation failed');});
manager.DocumentClosing.add((_s,e)=>{if(protectModified&&e.Document?.IsModified){e.Cancel=true;toast('Close canceled: this buffer has unsaved changes. Save it before closing.');}});
manager.ActiveContentChanged.add(()=>document.querySelectorAll('.activity[data-tool]').forEach(node=>node.classList.toggle('active',node.dataset.tool===manager.ActiveModel?.ContentId)));
try { if(localStorage.getItem(manager.StorageKey))manager.LoadFromStorage(); } catch {}
manager.ClearHistory();updateStatus();log(`DockingManager attached. ${AD.contents(manager.Layout).length} content items in the workspace.`,'ready');log('Drag a tab to reveal docking guides. Right-click for window commands.','hint');log('Layout XML / JSON, observable sources, keyboard navigation, and retained DOM are available.','ready');

const commands=()=>[
  {label:'New document',hint:'File',run:newDocument}, {label:'Save editor buffers',hint:'Ctrl S',run:saveBuffers}, {label:'Save workspace locally',hint:'Layout',run:saveWorkspace},
  {label:'Export layout as XML',hint:'File',run:()=>exportLayout('xml')},{label:'Export layout as JSON',hint:'File',run:()=>exportLayout('json')},{label:'Import layout',hint:'File',run:()=>$('#layout-file').click()},
  {label:'Undo layout change',hint:'Ctrl Z',run:()=>manager.Undo(),enabled:manager.CanUndo},{label:'Redo layout change',hint:'Ctrl Y',run:()=>manager.Redo(),enabled:manager.CanRedo},
  {label:'Float active window',hint:'Layout',run:()=>manager.Float(manager.ActiveModel)},{label:'Dock active window',hint:'Layout',run:()=>manager.Dock(manager.ActiveModel)},
  {label:'New vertical tab group',hint:'Layout',run:()=>manager.NewTabGroup(manager.ActiveModel,'Vertical')},{label:'New horizontal tab group',hint:'Layout',run:()=>manager.NewTabGroup(manager.ActiveModel,'Horizontal')},
  {label:'Reset development workspace',hint:'Layout',run:()=>applyPreset('development')},{label:'Focus workspace',hint:'Layout',run:()=>applyPreset('focus')},
  ...Object.entries(toolNames).map(([id,label])=>({label:`Show ${label}`,hint:'View',run:()=>showTool(id)})),
  {label:'Open live preview',hint:'View',run:()=>openFile('preview')},{label:'Open API reference',hint:'Help',run:()=>openFile('reference')},{label:'Keyboard shortcuts',hint:'Help',run:()=>openFile('shortcuts')},
  {label:'Open window navigator',hint:'Ctrl Tab',run:()=>manager.ShowNavigator()},{label:'Pop out active window',hint:'Browser window',run:()=>manager.PopOut(manager.ActiveModel)},
  {label:'Close active window',hint:'Ctrl F4',run:()=>manager.ActiveModel?.Close()}
];
function menu(name,button){let list=commands();if(name==='File')list=list.filter(x=>x.hint==='File'||x.hint==='Ctrl S');else if(name==='Edit')list=list.filter(x=>['Ctrl Z','Ctrl Y'].includes(x.hint));else if(name==='View')list=list.filter(x=>x.hint==='View');else if(name==='Layout')list=list.filter(x=>x.hint==='Layout');else if(name==='Help')list=list.filter(x=>x.hint==='Help');else list=list.filter(x=>['Ctrl Tab','Browser window','Ctrl F4'].includes(x.hint));const r=button.getBoundingClientRect();manager.ShowMenu(list.map(x=>({label:x.label,Execute:x.run,CanExecute:x.enabled!==false})),r.left,r.bottom+5,name);}
for(const button of document.querySelectorAll('[data-menu]'))button.addEventListener('click',()=>menu(button.dataset.menu,button));
for(const button of document.querySelectorAll('[data-tool]'))button.addEventListener('click',()=>showTool(button.dataset.tool));
$('#new-document').addEventListener('click',newDocument);$('#reset-layout').addEventListener('click',()=>applyPreset(currentPreset));$('#undo-layout').addEventListener('click',()=>manager.Undo());$('#redo-layout').addEventListener('click',()=>manager.Redo());$('#export-layout').addEventListener('click',()=>exportLayout('xml'));$('#status-save').addEventListener('click',saveWorkspace);$('#preset-select').addEventListener('change',e=>applyPreset(e.target.value));$('#theme-select').addEventListener('change',e=>{document.body.dataset.theme=e.target.value;manager.Theme=e.target.value;log(`Theme changed to ${e.target.value}.`);});$('#about-button').addEventListener('click',()=>openFile('reference'));$('#shortcuts-button').addEventListener('click',()=>openFile('shortcuts'));$('.brand').addEventListener('click',e=>{e.preventDefault();openFile('welcome');});
$('#layout-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>4*1024*1024)throw new Error('Layout files must be smaller than 4 MiB.');const text=await file.text();manager.LoadLayout(text,text.trimStart().startsWith('<')?'xml':'json');toast('Layout imported. Existing content was rebound by ContentId.');}catch(error){toast(`Import rejected: ${error.message}`);}finally{e.target.value='';}});
const dialog=$('#command-dialog'),commandInput=$('#command-input'),results=$('#command-results');
function renderCommands(){const items=commands().filter(item=>item.label.toLowerCase().includes(commandInput.value.toLowerCase()));results.replaceChildren(...items.map(item=>{const button=action('',()=>{dialog.close();item.run();},'command-result');button.disabled=item.enabled===false;button.append(h('span','',item.label),h('small','',item.hint));return button;}));}
function openCommands(){commandInput.value='';renderCommands();if(!dialog.open)dialog.showModal();commandInput.focus();}
$('#command-trigger').addEventListener('click',openCommands);commandInput.addEventListener('input',renderCommands);dialog.addEventListener('keydown',event=>{if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();const buttons=[...results.querySelectorAll('button:not(:disabled)')];const i=buttons.indexOf(document.activeElement),step=event.key==='ArrowDown'?1:-1;buttons[(i+step+buttons.length)%buttons.length]?.focus();}if(event.key==='Enter'&&document.activeElement===commandInput){event.preventDefault();results.querySelector('button:not(:disabled)')?.click();}});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openCommands();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'&&!event.defaultPrevented){event.preventDefault();saveBuffers();saveWorkspace();}});
window.demo={manager,AD,applyPreset,createLayout,openFile,showTool,newDocument,exportLayout,buffers,sourceDocuments,log,protectModified(value){protectModified=!!value;},openCommands};
